@helion.kernel()
def transposed_in_relu2(xT):
    M, N = xT.size()
    out = torch.empty(M, N, device=xT.device, dtype=xT.dtype)
    for tm, tn in hl.tile([M, N]):
        v = xT[tm, tn].to(torch.float32)
        out[tm, tn] = (v * v).to(out.dtype)
    return out
def make_inputs(shape):
    M, N = shape
    base = torch.randn(N, M, device='cuda', dtype=torch.bfloat16)
    return (base.t(),)

@helion.kernel()
def transposed_both_scale(xT, s):
    M, N = xT.size()
    out = torch.empty(N, M, device=xT.device, dtype=xT.dtype).t()
    for tm, tn in hl.tile([M, N]):
        out[tm, tn] = xT[tm, tn] * s
    return out
def make_inputs(shape):
    M, N = shape
    base = torch.randn(N, M, device='cuda', dtype=torch.float32)
    return (base.t(), 1.5)
